import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Euler } = ctx.THREE;

  // Root group
  const group = new Group();
  group.position.copy(new Vector3(-3.2, -0.3, 0));
  group.rotation.order = 'YXZ';

  // Load image texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create plane geometry (512x320 px aspect ratio)
  const planeGeom = new PlaneGeometry(2.56, 1.6); // ~2.56:1.6 aspect ratio

  // Build TSL material
  const colorNode = texture(null); // Placeholder; will be assigned after load
  const mat = new MeshBasicNodeMaterial({
    colorNode: colorNode,
    toneMapped: false,
    transparent: true,
  });

  // Create mesh
  const mesh = new Mesh(planeGeom, mat);
  mesh.castShadow = false;
  mesh.receiveShadow = false;

  // Load texture and assign to material
  texturePromise.then((tex) => {
    mat.colorNode = texture(tex);
    mat.needsUpdate = true;
  });

  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    planeGeom.dispose();
    mat.dispose();
    texturePromise.then((tex) => {
      if (tex) tex.dispose();
    });
  };

  return group;
}
